mapper.select:
select sum(t1.maintain_count) from tb_maintain_count t1
WHERE 1=1
and t1.material_code like concat(concat('%',#{maintainCountDto.materialCode}),'%')
and t1.created_time >= TO_DATE(#{maintainCountDto.startTime}, 'SYYYY-MM-DD HH24:MI:SS' )
and t1.created_time <= TO_DATE(#{maintainCountDto.endTime}, 'SYYYY-MM-DD HH24:MI:SS' )
 and ${tableColumn} = #{maintainCountDto.stackId}
 and t1.maintence_style = #{maintainCountDto.maintenceStyle}
 and t1.phases = #{maintainCountDto.phases}

